//! Requirements of the modelled puncture-repair system (R10) — SPEC.md §2.
//!
//! The workspace `trace.sh` keys requirement ids globally (F-053): the pilot
//! owns REQ-001..REQ-005 and CS-1 owns REQ-006..REQ-009, so CS-2 continues
//! the sequence at REQ-010 — exactly as SPEC.md §2 allocates them, so no
//! spec↔code id mapping is needed this time.
//!
//! Each requirement is a named trait generated by `model_core::requirement!`:
//! the required characteristic is a supertrait, the blanket impl is the only
//! impl, and a per-requirement `const fn` assertion backs every satisfaction
//! doc tag (F-020). The `/// REQ-NNN:` definition lines below are written
//! literally at the invocation sites so the workspace `trace.sh` sees them
//! (F-021); the report runs as a CI gate and fails on any requirement with no
//! verifying test.
//!
//! **Every requirement trait carries its own one-line
//! `#[diagnostic::on_unimplemented]`** phrased as the requirement and naming
//! its REQ id, passed through `requirement!`'s meta slot (R10 rule 8, F-044):
//! a failing marker's own attribute is ignored when the marker fails as a
//! supertrait obligation of a requirement bound — only the root obligation's
//! message is shown — so the requirement trait's message is the one modellers
//! will see. Marker-level attributes stay too, for direct marker bounds.
//!
//! Requirements are used **only as bounds** in process signatures (F-019) —
//! see `resources::processes::open_wheel` (REQ-010 on the member),
//! `resources::processes::patch_tube` (REQ-011 on the tube, REQ-013 on the
//! waste consumer), `resources::processes::buy_spare` (REQ-014 on the
//! counter) and `resources::processes::refit_and_inflate` (REQ-010 on the
//! member, REQ-012 on the tube).
//!
//! REQ-012 is **deliberately multi-type** (SPEC.md §8, review decision 7):
//! the checked patched tube and the new spare both carry compile-check-backed
//! satisfaction tags — the first real exercise of the F-055 note that
//! `satisfies!` resolution becomes many-to-many.

use crate::characteristics::{
    Airtight, ExactPriceCounter, Inducted, PunctureLocated, WasteStreamConsumer,
};

model_core::requirement! {
    /// REQ-010: Workshop tools (the workstand) may be used only by an inducted member.
    #[diagnostic::on_unimplemented(message = "this person may not use the workstand: `{Self}` is not an inducted workshop member (REQ-010)", label = "REQ-010: workshop tools may be used only by an inducted member", note = "induction is granted at the boundary (R12/R18): `qualify::<Induction, BUDGET>(person)` wraps a `Person` into a `Qualified` member")]
    pub trait Req010InductedAtTheWorkstand: (Inducted);
    assert = assert_req010;
}

model_core::requirement! {
    /// REQ-011: Only a located puncture may be patched (no blind patching).
    #[diagnostic::on_unimplemented(message = "this tube may not be patched: `{Self}` does not have a located puncture (REQ-011)", label = "REQ-011: only a located puncture may be patched", note = "locating is a process (one type per state, R9): `find_hole` turns a `PuncturedTube` into a `LocatedTube` - only that state can be patched")]
    pub trait Req011LocatedBeforePatching: (PunctureLocated);
    assert = assert_req011;
}

model_core::requirement! {
    /// REQ-012: A wheel may be refitted only with an airtight tube - one that is patched and checked, or new.
    #[diagnostic::on_unimplemented(message = "this tube may not be fitted to the wheel: `{Self}` is not airtight (REQ-012: patched-and-checked, or new)", label = "REQ-012: a wheel may be refitted only with an airtight tube", note = "two states satisfy this requirement (deliberately multi-type): `check_patch` produces the checked `CheckedTube`, and `buy_spare` supplies a new `SpareTube`")]
    pub trait Req012AirtightTubeOnly: (Airtight);
    assert = assert_req012;
}

model_core::requirement! {
    /// REQ-013: All failed patches must reach the workshop waste stream.
    #[diagnostic::on_unimplemented(message = "failed patches may not go here: `{Self}` is not the workshop waste stream (REQ-013)", label = "REQ-013: all failed patches must reach the workshop waste stream", note = "the dedicated consumer is the `WasteStream` (an unbounded placeholder sink, R15); `patch_tube` feeds the spent patch to it inside the process, so failed patches never exist loose")]
    pub trait Req013FailedPatchesToWasteStream: (WasteStreamConsumer);
    assert = assert_req013;
}

model_core::requirement! {
    /// REQ-014: Spare tubes are sold only at the counter's listed price.
    #[diagnostic::on_unimplemented(message = "spare tubes may not be bought here: `{Self}` is not the parts counter selling at its listed price (REQ-014)", label = "REQ-014: spare tubes are sold only at the counter's listed price", note = "the counter consumes only `Money<650>` (the listed price, F-051): paying any other amount is a type error naming the right price")]
    pub trait Req014ListedPriceOnly: (ExactPriceCounter);
    assert = assert_req014;
}
